const gameHtml = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>轮回问道</title>\n  <style>\n    :root {\n      color-scheme: dark;\n      --bg: #121510;\n      --panel: #20251d;\n      --panel-2: #2a3127;\n      --ink: #f4efdf;\n      --muted: #b9b39f;\n      --accent: #d8b35f;\n      --good: #7fc8a9;\n      --bad: #d97869;\n      --line: rgba(244, 239, 223, 0.15);\n      --shadow: rgba(0, 0, 0, 0.38);\n    }\n\n    * {\n      box-sizing: border-box;\n    }\n\n    body {\n      margin: 0;\n      min-height: 100vh;\n      display: grid;\n      place-items: center;\n      background:\n        radial-gradient(circle at 18% 10%, rgba(216, 179, 95, 0.18), transparent 28rem),\n        radial-gradient(circle at 82% 86%, rgba(127, 200, 169, 0.12), transparent 30rem),\n        linear-gradient(135deg, #0d100d 0%, var(--bg) 46%, #1a1b15 100%);\n      color: var(--ink);\n      font-family: \"Microsoft YaHei\", \"PingFang SC\", system-ui, sans-serif;\n      line-height: 1.65;\n      padding: 24px;\n    }\n\n    main {\n      width: min(1060px, 100%);\n      min-height: min(740px, calc(100vh - 48px));\n      display: grid;\n      grid-template-columns: 1fr 300px;\n      border: 1px solid var(--line);\n      background: rgba(32, 37, 29, 0.9);\n      box-shadow: 0 24px 70px var(--shadow);\n    }\n\n    .story {\n      display: flex;\n      flex-direction: column;\n      padding: clamp(22px, 4vw, 42px);\n      border-right: 1px solid var(--line);\n    }\n\n    h1 {\n      margin: 0 0 6px;\n      font-size: clamp(32px, 6vw, 58px);\n      font-weight: 800;\n      letter-spacing: 0;\n      line-height: 1.05;\n    }\n\n    .subtitle {\n      margin: 0 0 28px;\n      color: var(--muted);\n      font-size: 15px;\n    }\n\n    #scene-title {\n      margin: 0 0 12px;\n      font-size: 24px;\n      color: var(--accent);\n    }\n\n    #scene-text {\n      margin: 0;\n      max-width: 72ch;\n      font-size: 18px;\n      white-space: pre-line;\n    }\n\n    .sketch {\n      width: min(520px, 100%);\n      margin: 24px 0 0;\n      border: 1px solid var(--line);\n      background: rgba(244, 239, 223, 0.035);\n      aspect-ratio: 16 / 9;\n      overflow: hidden;\n    }\n\n    .sketch svg {\n      width: 100%;\n      height: 100%;\n      display: block;\n    }\n\n    .choices {\n      display: grid;\n      gap: 12px;\n      margin-top: auto;\n      padding-top: 32px;\n    }\n\n    button {\n      min-height: 48px;\n      border: 1px solid var(--line);\n      border-radius: 6px;\n      background: var(--panel-2);\n      color: var(--ink);\n      font: inherit;\n      text-align: left;\n      padding: 11px 14px;\n      cursor: pointer;\n      transition: transform 150ms ease, border-color 150ms ease, background 150ms ease;\n    }\n\n    button:hover,\n    button:focus-visible {\n      outline: none;\n      transform: translateY(-1px);\n      border-color: rgba(216, 179, 95, 0.72);\n      background: #333b2f;\n    }\n\n    aside {\n      padding: 28px 24px;\n      background: rgba(12, 14, 11, 0.34);\n    }\n\n    .side-block + .side-block {\n      margin-top: 24px;\n      padding-top: 22px;\n      border-top: 1px solid var(--line);\n    }\n\n    h2 {\n      margin: 0 0 12px;\n      font-size: 15px;\n      color: var(--muted);\n      font-weight: 700;\n    }\n\n    ul {\n      list-style: none;\n      padding: 0;\n      margin: 0;\n      display: grid;\n      gap: 8px;\n    }\n\n    li {\n      display: flex;\n      justify-content: space-between;\n      gap: 14px;\n      padding: 8px 10px;\n      border: 1px solid var(--line);\n      background: rgba(244, 239, 223, 0.04);\n      color: var(--muted);\n      font-size: 14px;\n    }\n\n    li strong {\n      color: var(--ink);\n      text-align: right;\n    }\n\n    .meter {\n      height: 11px;\n      border: 1px solid var(--line);\n      background: #11130f;\n      overflow: hidden;\n    }\n\n    .meter span {\n      display: block;\n      height: 100%;\n      background: linear-gradient(90deg, var(--good), var(--accent));\n      transition: width 260ms ease;\n    }\n\n    .log {\n      color: var(--muted);\n      font-size: 14px;\n      white-space: pre-line;\n    }\n\n    .ending {\n      color: var(--good);\n      font-weight: 700;\n    }\n\n    .warning {\n      color: var(--bad);\n    }\n\n    .audio-toggle {\n      width: 100%;\n      min-height: 42px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 12px;\n      text-align: left;\n    }\n\n    .audio-toggle strong {\n      color: var(--good);\n      font-weight: 700;\n    }\n\n    @media (max-width: 800px) {\n      body {\n        padding: 0;\n      }\n\n      main {\n        min-height: 100vh;\n        grid-template-columns: 1fr;\n        border: 0;\n      }\n\n      .story {\n        min-height: 66vh;\n        border-right: 0;\n        border-bottom: 1px solid var(--line);\n      }\n    }\n  </style>\n</head>\n<body>\n  <main>\n    <section class=\"story\" aria-live=\"polite\">\n      <h1>轮回问道</h1>\n      <p class=\"subtitle\">带着记忆重生的修仙文字模拟器</p>\n      <h2 id=\"scene-title\"></h2>\n      <p id=\"scene-text\"></p>\n      <div id=\"scene-sketch\" class=\"sketch\" aria-label=\"当前道途简笔画\"></div>\n      <div id=\"choices\" class=\"choices\"></div>\n    </section>\n\n    <aside>\n      <section class=\"side-block\">\n        <h2>这一世</h2>\n        <ul>\n          <li><span>世数</span><strong id=\"life\"></strong></li>\n          <li><span>境界</span><strong id=\"realm\"></strong></li>\n          <li><span>流派</span><strong id=\"path\"></strong></li>\n          <li><span>寿元</span><strong id=\"years\"></strong></li>\n        </ul>\n      </section>\n\n      <section class=\"side-block\">\n        <h2>修为</h2>\n        <div class=\"meter\" aria-label=\"修为进度\"><span id=\"qi-bar\"></span></div>\n        <ul>\n          <li><span>灵力</span><strong id=\"qi\"></strong></li>\n          <li><span>道德</span><strong id=\"virtue\"></strong></li>\n          <li><span>因果</span><strong id=\"karma\"></strong></li>\n        </ul>\n      </section>\n\n      <section class=\"side-block\">\n        <h2>轮回记忆</h2>\n        <ul>\n          <li><span>记忆点</span><strong id=\"memory\"></strong></li>\n          <li><span>悟性</span><strong id=\"talent\"></strong></li>\n          <li><span>天命碎片</span><strong id=\"fragments\"></strong></li>\n        </ul>\n      </section>\n\n      <section class=\"side-block\">\n        <h2>记录</h2>\n        <p id=\"log\" class=\"log\"></p>\n      </section>\n\n      <section class=\"side-block\">\n        <h2>声音</h2>\n        <button id=\"audio-toggle\" class=\"audio-toggle\" type=\"button\">\n          <span>音效 / 音乐</span>\n          <strong id=\"audio-state\">关</strong>\n        </button>\n      </section>\n    </aside>\n  </main>\n\n  <script>\n    const realms = [\"凡人\", \"炼气\", \"筑基\", \"金丹\", \"元婴\", \"化神\", \"渡劫\", \"飞升\"];\n\n    const freshLife = {\n      scene: \"birth\",\n      life: 1,\n      realm: 0,\n      qi: 0,\n      years: 8,\n      virtue: 50,\n      karma: 0,\n      memory: 0,\n      talent: 0,\n      fragments: 0,\n      path: \"未定\",\n      turn: 0,\n      flags: {},\n      log: \"你在山脚小村醒来，脑海里残留着不属于孩童的旧梦。\"\n    };\n\n    function cloneData(value) {\n      if (typeof structuredClone === \"function\") return structuredClone(value);\n      return JSON.parse(JSON.stringify(value));\n    }\n\n    let state = cloneData(freshLife);\n\n    const scenes = {\n      birth: {\n        title: \"山脚重生\",\n        text: () => `第 ${state.life} 世，你又在同一个清晨醒来。\\n\\n窗外青山如洗，村口老槐树下有一位白发道人摆摊算命。你记得前世许多片段：有人正道登天，有人邪法速成，也有人因道德亏损，飞升时坠入幽冥，被迫重走人间。\\n\\n这一次，你要怎样开局？`,\n        choices: [\n          {\n            text: \"拜入青云观，走稳健正修\",\n            to: \"sect\",\n            effect: s => {\n              s.path = \"正修\";\n              s.qi += 16 + s.talent;\n              s.virtue += 10;\n              s.years += 2;\n              s.log = \"青云观传你吐纳法。慢一些，但根基清明。\";\n            }\n          },\n          {\n            text: \"向散修换血煞功，走偏锋邪修\",\n            to: \"market\",\n            effect: s => {\n              s.path = \"邪修\";\n              s.qi += 26 + s.talent;\n              s.karma += 8;\n              s.virtue -= 6;\n              s.log = \"血煞功不必伤人也能修，只是更容易被欲念牵引。\";\n            }\n          },\n          {\n            text: \"用记忆点换开局悟性\",\n            to: \"birth\",\n            requires: s => s.memory >= 3,\n            effect: s => {\n              s.memory -= 3;\n              s.talent += 5;\n              s.log = \"你把一段轮回记忆炼成直觉。下一次吐纳，天地像慢了半拍。\";\n            }\n          },\n          {\n            text: \"追问白发道人：轮回是谁布下的？\",\n            to: \"oldMan\",\n            requires: s => s.fragments >= 2 || s.life >= 3,\n            effect: s => {\n              s.log = \"道人看了你很久：能问到这里，说明你已经不止活过一次。\";\n            }\n          }\n        ]\n      },\n\n      oldMan: {\n        title: \"老槐树下\",\n        text: \"白发道人摊开掌心，里面不是铜钱，而是一枚裂开的天命印。\\n\\n他说：所谓轮回，并非天罚。三千年前仙界断路，有人把凡间做成炉，把一次次人生做成柴，想炼出一个能补天的人。\\n\\n你可以顺着炉火变强，也可以在足够强时打破炉壁。\",\n        choices: [\n          {\n            text: \"收下天命印碎片\",\n            to: \"birth\",\n            once: \"oldManShard\",\n            effect: s => {\n              s.fragments += 1;\n              s.memory += 1;\n              s.log = \"碎片融入识海。你隐约看见飞升门后，并不全是光。\";\n            }\n          },\n          { text: \"暂时离开\", to: \"birth\" }\n        ]\n      },\n\n      sect: {\n        title: \"青云观\",\n        text: \"你在观中修行十年。师兄弟争夺内门名额，山下又传来妖潮将至的消息。\\n\\n正修讲克己守心，但不是软弱。真正的正，是强大之后仍肯护人。\",\n        choices: [\n          {\n            text: \"苦修破境\",\n            to: \"tribulation\",\n            effect: s => {\n              s.qi += 30 + s.talent;\n              s.years -= 2;\n              s.log = \"你闭关苦修，灵台澄澈。\";\n            }\n          },\n          {\n            text: \"下山护村，积累功德\",\n            to: \"demon\",\n            effect: s => {\n              s.virtue += 18;\n              s.qi += 12 + s.talent;\n              s.years -= 1;\n              s.log = \"你救下许多凡人，也看见修士力量该落向哪里。\";\n            }\n          },\n          {\n            text: \"偷看禁卷，研究邪法的边界\",\n            to: \"forbidden\",\n            effect: s => {\n              s.path = \"兼修\";\n              s.qi += 20 + s.talent;\n              s.karma += 4;\n              s.log = \"禁卷不只记载恶，也记载人心的险。你决定只取术，不取贪。\";\n            }\n          }\n        ]\n      },\n\n      market: {\n        title: \"黑市洞府\",\n        text: \"邪修集市藏在雨夜山腹。这里出售速成法、替劫符、夺灵阵，也有人只把邪法当作刀，绝不砍向无辜者。\\n\\n力量来得越快，越需要自己握紧方向。\",\n        choices: [\n          {\n            text: \"修血煞功，但只炼凶兽血气\",\n            to: \"tribulation\",\n            effect: s => {\n              s.qi += 34 + s.talent;\n              s.karma += 6;\n              s.virtue += 3;\n              s.years -= 2;\n              s.log = \"你避开伤人捷径，进境仍快，只是心魔更早找上门。\";\n            }\n          },\n          {\n            text: \"买下替劫符，留给无辜者\",\n            to: \"demon\",\n            effect: s => {\n              s.qi += 10 + s.talent;\n              s.virtue += 15;\n              s.karma -= 4;\n              s.years -= 1;\n              s.log = \"黑市商人笑你亏本。可你知道，有些账不在灵石里算。\";\n            }\n          },\n          {\n            text: \"贪快吞服三枚赤魂丹\",\n            to: \"heartDemon\",\n            effect: s => {\n              s.qi += 46 + s.talent;\n              s.virtue -= 16;\n              s.karma += 18;\n              s.years -= 3;\n              s.log = \"药力汹涌如火，你听见自己的欲望在丹田里说话。\";\n            }\n          }\n        ]\n      },\n\n      forbidden: {\n        title: \"禁卷残页\",\n        text: \"残页上写着一句话：正邪不在法，在用法之人。\\n\\n你发现所谓邪法本源是古仙补天术的残缺部分。它能吞浊气、炼怨念，若无人约束，也能吞人心。\",\n        choices: [\n          {\n            text: \"立誓只炼怨浊，不夺生魂\",\n            to: \"tribulation\",\n            effect: s => {\n              s.qi += 25 + s.talent;\n              s.virtue += 8;\n              s.karma -= 2;\n              s.fragments += 1;\n              s.log = \"誓言落下时，天命印微微发热。\";\n            }\n          },\n          {\n            text: \"把残页交给师门共同研究\",\n            to: \"sectTruth\",\n            effect: s => {\n              s.virtue += 16;\n              s.qi += 14 + s.talent;\n              s.log = \"长老没有毁掉残页，只问你：若法可救人，何必先给它定罪？\";\n            }\n          }\n        ]\n      },\n\n      demon: {\n        title: \"山下妖潮\",\n        text: \"妖潮并非天灾，而是有人抽走山脉灵脉，逼灵兽失巢。你站在村口，看见上一世害死你的魔修也在救孩子。\\n\\n故事从来没有简单到只分黑白。\",\n        choices: [\n          {\n            text: \"救人优先，放过那名魔修\",\n            to: \"sectTruth\",\n            effect: s => {\n              s.virtue += 16;\n              s.karma -= 5;\n              s.qi += 15 + s.talent;\n              s.log = \"魔修临走前丢给你半枚天命印碎片。\";\n              s.fragments += 1;\n            }\n          },\n          {\n            text: \"追查抽灵脉的幕后人\",\n            to: \"sectTruth\",\n            effect: s => {\n              s.qi += 24 + s.talent;\n              s.years -= 2;\n              s.log = \"线索指向仙盟。所谓正道魁首，正在偷凡间的未来。\";\n              s.fragments += 1;\n            }\n          },\n          {\n            text: \"借妖潮磨炼战力\",\n            to: \"tribulation\",\n            effect: s => {\n              s.qi += 38 + s.talent;\n              s.karma += 7;\n              s.virtue -= 4;\n              s.years -= 2;\n              s.log = \"你没有害人，但你开始把灾难看成台阶。这个念头很危险。\";\n            }\n          }\n        ]\n      },\n\n      sectTruth: {\n        title: \"仙盟密令\",\n        text: \"你终于查到真相：仙盟每百年挑选“可飞升者”，不是为了送他们成仙，而是送去仙界裂隙当燃料。\\n\\n白发道人、魔修、青云观长老，都曾是炉中薪柴。轮回让你变强，也在筛选你的心。\",\n        choices: [\n          {\n            text: \"公开密令，联合正邪修士\",\n            to: \"tribulation\",\n            effect: s => {\n              s.virtue += 20;\n              s.qi += 20 + s.talent;\n              s.karma -= 8;\n              s.fragments += 1;\n              s.log = \"越来越多人站到你身后。正邪不是阵营，选择才是。\";\n            }\n          },\n          {\n            text: \"独自潜入仙盟夺天梯钥\",\n            to: \"heartDemon\",\n            effect: s => {\n              s.qi += 42 + s.talent;\n              s.karma += 10;\n              s.years -= 2;\n              s.log = \"你赢得很快，也失去很快。孤身入局，心魔最爱这种时刻。\";\n            }\n          }\n        ]\n      },\n\n      tribulation: {\n        title: \"破境雷劫\",\n        text: () => `雷云压下，你的修为抵达瓶颈。\\n\\n当前灵力：${state.qi}。灵力越高，破境越稳；道德越低，天劫越重；因果越深，心魔越强。`,\n        choices: [\n          {\n            text: \"迎雷破境\",\n            to: \"afterBreak\",\n            effect: s => {\n              const threshold = 28 + s.realm * 22 + Math.max(0, 50 - s.virtue) + Math.max(0, s.karma);\n              if (s.qi >= threshold) {\n                s.realm += 1;\n                s.qi = Math.max(0, s.qi - threshold + 8);\n                s.years += 5;\n                s.memory += 1;\n                s.log = `你扛过雷劫，踏入${realms[s.realm]}。这次经验化作 1 点轮回记忆。`;\n              } else {\n                s.scene = \"death\";\n                s.log = \"雷光落下，你知道还差一点。下一世，你会记住这一道雷。\";\n              }\n            }\n          },\n          {\n            text: \"沉心补德，先化解因果\",\n            to: \"afterBreak\",\n            effect: s => {\n              s.virtue += 12;\n              s.karma = Math.max(0, s.karma - 10);\n              s.qi += 6 + s.talent;\n              s.years -= 1;\n              s.log = \"你没有急着变强。很多时候，慢一步才走得更远。\";\n            }\n          },\n          {\n            text: \"以邪法吞雷，强行提速\",\n            to: \"heartDemon\",\n            effect: s => {\n              s.qi += 38 + s.talent;\n              s.karma += 14;\n              s.virtue -= 10;\n              s.log = \"雷霆被你炼入血脉。力量是真的，代价也是真的。\";\n            }\n          }\n        ]\n      },\n\n      afterBreak: {\n        title: \"道途抉择\",\n        text: () => `你如今是${realms[state.realm]}修士。轮回记忆越积越厚，前世失败正在变成今生的台阶。\\n\\n若继续修行，你可能飞升、坠入幽冥，或者揭开天命炉的终局。`,\n        choices: [\n          {\n            text: \"继续这一世\",\n            to: \"sect\",\n            requires: s => s.realm < 5 && s.years > 0,\n            effect: s => {\n              s.years -= 1;\n              s.log = \"你收拾行囊，再入尘世。\";\n            }\n          },\n          {\n            text: \"尝试飞升\",\n            to: \"ascend\",\n            requires: s => s.realm >= 5\n          },\n          {\n            text: \"直面天命炉，打破轮回\",\n            to: \"breakWheel\",\n            requires: s => s.fragments >= 4 && s.realm >= 4\n          },\n          {\n            text: \"寿元耗尽，坦然入轮回\",\n            to: \"death\",\n            requires: s => s.years <= 0\n          }\n        ]\n      },\n\n      heartDemon: {\n        title: \"心魔问道\",\n        text: \"心魔不是另一个你，而是你每次想走捷径时留下的影子。\\n\\n它问：既然轮回能重来，为什么还要珍惜这一世的人？\",\n        choices: [\n          {\n            text: \"承认贪念，但不让它掌舵\",\n            to: \"tribulation\",\n            effect: s => {\n              s.virtue += 10;\n              s.karma = Math.max(0, s.karma - 8);\n              s.memory += 1;\n              s.log = \"你没有否认黑暗，只是把灯重新点亮。\";\n            }\n          },\n          {\n            text: \"以意志镇压心魔\",\n            to: \"afterBreak\",\n            effect: s => {\n              s.qi += 20 + s.talent;\n              s.karma += 5;\n              s.log = \"你暂时赢了，但镇压不是化解。\";\n            }\n          },\n          {\n            text: \"任由心魔接管\",\n            to: \"hell\",\n            effect: s => {\n              s.virtue -= 30;\n              s.karma += 30;\n              s.log = \"你得到了力量，也把自己从人间的牵挂里拔了出来。\";\n            }\n          }\n        ]\n      },\n\n      ascend: {\n        title: \"飞升门前\",\n        text: () => `天门打开，金光照落。可门后传来锁链声。\\n\\n你的道德为 ${state.virtue}，因果为 ${state.karma}。道德越低，飞升越像审判；因果越深，越容易被打入幽冥重走人间。`,\n        choices: [\n          {\n            text: \"踏入天门\",\n            to: \"ascendResult\",\n            effect: s => {\n              const burden = Math.max(0, 65 - s.virtue) + s.karma;\n              if (burden >= 55) {\n                s.scene = \"hell\";\n                s.log = \"天门金光一转成黑。你不是飞升，而是被因果拖入幽冥。\";\n              } else if (s.fragments >= 4 && s.virtue >= 60) {\n                s.scene = \"trueAscend\";\n                s.log = \"你看穿天门后的裂隙，终于有资格选择自己的飞升。\";\n              } else {\n                s.scene = \"falseAscend\";\n                s.log = \"你飞升了，却发现自己只是被送上更高处的炉台。\";\n              }\n            }\n          },\n          {\n            text: \"退回人间，先补全因果\",\n            to: \"sect\",\n            effect: s => {\n              s.virtue += 8;\n              s.karma = Math.max(0, s.karma - 8);\n              s.log = \"能退一步的人，往往比只会往前冲的人更接近大道。\";\n            }\n          }\n        ]\n      },\n\n      breakWheel: {\n        title: \"天命炉底\",\n        text: \"四枚天命碎片合一，照出炉底真相：仙界裂隙需要燃料，但并非必须烧人。\\n\\n若有人愿意把正修的守心、邪修的炼浊、轮回的记忆合成新法，就能补天而不献祭众生。\",\n        choices: [\n          {\n            text: \"以众生功德补天，终止轮回\",\n            to: \"trueEnding\",\n            requires: s => s.virtue >= 70 && s.realm >= 4\n          },\n          {\n            text: \"以自身为钥，封炉一世\",\n            to: \"sacrifice\",\n            requires: s => s.virtue >= 45\n          },\n          {\n            text: \"强夺天命炉，成为新炉主\",\n            to: \"hell\",\n            effect: s => {\n              s.virtue -= 40;\n              s.karma += 50;\n              s.log = \"你赢过了旧炉主，却变成了下一道枷锁。幽冥已经在等你。\";\n            }\n          }\n        ]\n      },\n\n      trueAscend: {\n        title: \"结局：清明飞升\",\n        text: \"你没有被天门吞没，而是带着人间万千因果穿门而过。\\n\\n仙界裂隙前，你立下新规：飞升不是献祭，强者不该把弱者当作柴薪。从此正邪各修其法，同受一条底线约束：不伤无辜，不弃人间。\",\n        ending: true,\n        choices: [\n          { text: \"带着更多记忆再入轮回\", rebirth: true },\n          { text: \"彻底重开\", hardReset: true }\n        ]\n      },\n\n      falseAscend: {\n        title: \"结局：炉上仙\",\n        text: \"你登上仙界，却发现脚下是无数前辈烧尽后的灰。\\n\\n这一世不算失败。你记住了天门后的真相。下一世，你会更早寻找天命碎片。\",\n        ending: true,\n        choices: [\n          { text: \"带着真相重生\", rebirth: true, bonus: { memory: 3, fragments: 1 } },\n          { text: \"彻底重开\", hardReset: true }\n        ]\n      },\n\n      trueEnding: {\n        title: \"真结局：万世不再为炉\",\n        text: \"你把轮回记忆还给所有曾被炉火吞没的人。\\n\\n正修守住底线，邪修炼化浊气，凡人不再被当成命数里的消耗。天裂仍在，但补天终于不需要牺牲无辜者。\\n\\n你没有成为传说里的神。你只是让后来者不必一次次重生，才有资格活成自己。\",\n        ending: true,\n        choices: [\n          { text: \"以新天道再开一局\", hardReset: true }\n        ]\n      },\n\n      sacrifice: {\n        title: \"结局：一世封炉\",\n        text: \"你没有足够功德补天，只能以自身为钥，封住天命炉一世。\\n\\n人间获得百年喘息。百年后，也许会有另一个带着记忆的人醒来，接过你没走完的路。\",\n        ending: true,\n        choices: [\n          { text: \"下一世接续此愿\", rebirth: true, bonus: { memory: 2, virtue: 8 } },\n          { text: \"彻底重开\", hardReset: true }\n        ]\n      },\n\n      death: {\n        title: \"结局：身死道未消\",\n        text: \"这一世到此为止。死亡像一扇旧门，门后仍是那个山脚清晨。\\n\\n你失去了修为，却留下经验。轮回并不温柔，但它允许你把失败变成下一次的力量。\",\n        ending: true,\n        choices: [\n          { text: \"带着记忆重生\", rebirth: true, bonus: { memory: 2 } },\n          { text: \"彻底重开\", hardReset: true }\n        ]\n      },\n\n      hell: {\n        title: \"结局：幽冥重走人间\",\n        text: \"因果沉重，道德亏损，天门化作幽冥。\\n\\n你没有被永久惩罚，只是被迫从最艰难的人间再走一遍：少一点天赋，多一点债。只有重新理解力量为何而用，才可能再次靠近飞升。\",\n        ending: true,\n        choices: [\n          { text: \"从幽冥转生\", rebirth: true, hell: true },\n          { text: \"彻底重开\", hardReset: true }\n        ]\n      },\n\n      ascendResult: {\n        title: \"天门之后\",\n        text: \"天门正在判断你的因果。\",\n        choices: []\n      }\n    };\n\n    const sceneTitle = document.querySelector(\"#scene-title\");\n    const sceneText = document.querySelector(\"#scene-text\");\n    const sceneSketch = document.querySelector(\"#scene-sketch\");\n    const choices = document.querySelector(\"#choices\");\n    const life = document.querySelector(\"#life\");\n    const realm = document.querySelector(\"#realm\");\n    const path = document.querySelector(\"#path\");\n    const years = document.querySelector(\"#years\");\n    const qiBar = document.querySelector(\"#qi-bar\");\n    const qi = document.querySelector(\"#qi\");\n    const virtue = document.querySelector(\"#virtue\");\n    const karma = document.querySelector(\"#karma\");\n    const memory = document.querySelector(\"#memory\");\n    const talent = document.querySelector(\"#talent\");\n    const fragments = document.querySelector(\"#fragments\");\n    const log = document.querySelector(\"#log\");\n    const audioToggle = document.querySelector(\"#audio-toggle\");\n    const audioState = document.querySelector(\"#audio-state\");\n    const AudioContextClass = window.AudioContext || window.webkitAudioContext;\n\n    const audio = {\n      ctx: null,\n      enabled: false,\n      drones: [],\n      timer: null,\n\n      async start() {\n        if (!AudioContextClass) {\n          if (audioState) audioState.textContent = \"不支持\";\n          return;\n        }\n\n        try {\n          if (!this.ctx) this.ctx = new AudioContextClass();\n          if (this.ctx.state === \"suspended\") await this.ctx.resume();\n          this.enabled = true;\n          this.startMusic();\n          this.play(\"start\");\n          this.updateLabel();\n        } catch (error) {\n          this.enabled = false;\n          this.updateLabel();\n        }\n      },\n\n      stop() {\n        this.enabled = false;\n        this.stopMusic();\n        this.updateLabel();\n      },\n\n      toggle() {\n        if (this.enabled) this.stop();\n        else this.start();\n      },\n\n      updateLabel() {\n        if (audioState) audioState.textContent = this.enabled ? \"开\" : \"关\";\n      },\n\n      startMusic() {\n        if (!this.ctx || this.drones.length) return;\n        const now = this.ctx.currentTime;\n        const master = this.ctx.createGain();\n        master.gain.setValueAtTime(0.035, now);\n        master.connect(this.ctx.destination);\n\n        [110, 165, 220].forEach((frequency, index) => {\n          const osc = this.ctx.createOscillator();\n          const gain = this.ctx.createGain();\n          osc.type = index === 1 ? \"triangle\" : \"sine\";\n          osc.frequency.setValueAtTime(frequency, now);\n          gain.gain.setValueAtTime(index === 0 ? 0.52 : 0.22, now);\n          osc.connect(gain);\n          gain.connect(master);\n          osc.start();\n          this.drones.push({ osc, gain, master });\n        });\n\n        this.timer = window.setInterval(() => {\n          if (!this.enabled || !this.ctx) return;\n          const t = this.ctx.currentTime;\n          const note = [330, 392, 440, 523][Math.floor(Math.random() * 4)];\n          this.tone(note, 0.65, 0.025, \"sine\", t);\n        }, 5200);\n      },\n\n      stopMusic() {\n        if (this.timer) window.clearInterval(this.timer);\n        this.timer = null;\n        this.drones.forEach(({ osc, gain }) => {\n          try {\n            const now = this.ctx.currentTime;\n            gain.gain.cancelScheduledValues(now);\n            gain.gain.setTargetAtTime(0, now, 0.08);\n            osc.stop(now + 0.22);\n          } catch (error) {}\n        });\n        this.drones = [];\n      },\n\n      tone(frequency, duration = 0.16, volume = 0.06, type = \"sine\", startTime) {\n        if (!this.enabled || !this.ctx) return;\n        try {\n          const now = startTime || this.ctx.currentTime;\n          const osc = this.ctx.createOscillator();\n          const gain = this.ctx.createGain();\n          osc.type = type;\n          osc.frequency.setValueAtTime(frequency, now);\n          gain.gain.setValueAtTime(0.0001, now);\n          gain.gain.exponentialRampToValueAtTime(volume, now + 0.025);\n          gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);\n          osc.connect(gain);\n          gain.connect(this.ctx.destination);\n          osc.start(now);\n          osc.stop(now + duration + 0.03);\n        } catch (error) {}\n      },\n\n      play(kind) {\n        if (!this.enabled || !this.ctx) return;\n        const now = this.ctx.currentTime;\n        const patterns = {\n          click: [[220, 0], [330, 0.045]],\n          start: [[196, 0], [294, 0.09], [392, 0.18]],\n          break: [[330, 0], [495, 0.08], [660, 0.16]],\n          rebirth: [[147, 0], [220, 0.11], [330, 0.24]],\n          ending: [[392, 0], [523, 0.13], [784, 0.34]],\n          danger: [[110, 0], [98, 0.12], [82, 0.24]]\n        };\n        (patterns[kind] || patterns.click).forEach(([frequency, offset]) => {\n          this.tone(frequency, 0.18, kind === \"danger\" ? 0.07 : 0.05, kind === \"danger\" ? \"sawtooth\" : \"sine\", now + offset);\n        });\n      }\n    };\n\n    if (audioToggle) audioToggle.addEventListener(\"click\", () => audio.toggle());\n\n    function textOf(value) {\n      return typeof value === \"function\" ? value() : value;\n    }\n\n    function hashText(text) {\n      let hash = 2166136261;\n      for (let index = 0; index < text.length; index += 1) {\n        hash ^= text.charCodeAt(index);\n        hash = Math.imul(hash, 16777619);\n      }\n      return hash >>> 0;\n    }\n\n    function pick(list, salt = \"\") {\n      return list[hashText(`${state.scene}|${state.life}|${state.turn}|${state.realm}|${state.virtue}|${state.karma}|${salt}`) % list.length];\n    }\n\n    function variedSceneText(scene, baseText) {\n      if (scene.ending) return baseText;\n\n      const weather = [\n        \"薄雾从山谷里漫上来，像上一世没有说完的话。\",\n        \"风掠过竹林，几片落叶在你脚边排成卦象。\",\n        \"远处钟声忽近忽远，仿佛有人在另一条时间线上叩门。\",\n        \"灵气在空气里浮动，像水面细碎的月光。\"\n      ];\n      const morality = state.virtue >= 70\n        ? [\"你心口有一缕清光，照得许多选择都没那么浑浊。\", \"功德不替你赢，却让雷云迟疑了一息。\"]\n        : state.virtue <= 35\n          ? [\"因果像冷铁贴在腕上，提醒你有些账还没有还。\", \"你能感觉到幽冥很近，近到像一口井在脚下张开。\"]\n          : [\"人间的善恶没有替你做决定，只把重量放回你掌心。\", \"你仍在路中间，左边是捷径，右边是长阶。\"];\n      const pathTone = state.path === \"邪修\"\n        ? [\"血煞功在经脉里低鸣，像一柄尚未出鞘的刀。\", \"偏锋之法给你速度，也逼你更早回答自己为何修行。\"]\n        : state.path === \"正修\"\n          ? [\"吐纳之间，灵台如井，倒映出更高处的云。\", \"正修不让你少受苦，只让你在苦里不轻易变形。\"]\n          : state.path === \"兼修\"\n            ? [\"正邪两脉在丹田边缘相望，像两条最终汇入一处的河。\", \"你开始明白，法门有阴阳，底线却不能分裂。\"]\n            : [\"旧梦贴着识海翻动，你还没有决定这一世要走哪条路。\"];\n      const omen = state.karma >= 30\n        ? [\"乌线缠上天边，某个债主正在命数里转身。\"]\n        : state.fragments >= 3\n          ? [\"天命碎片微微发热，画出一扇并不完整的门。\"]\n          : [\"这一次轮回仍有空白，空白处也许藏着新路。\"];\n\n      return `${pick(weather, \"weather\")}\\n${pick(morality, \"morality\")}\\n${pick(pathTone, \"path\")}\\n${pick(omen, \"omen\")}\\n\\n${baseText}`;\n    }\n\n    function sketchForState(scene) {\n      const tone = state.virtue >= 65 ? \"#7fc8a9\" : state.virtue <= 35 ? \"#d97869\" : \"#d8b35f\";\n      const shadow = state.karma >= 30 ? \"#d97869\" : \"#6f7967\";\n      const sky = state.scene === \"hell\" || state.scene === \"heartDemon\" ? \"#2b1d20\" : \"#171d16\";\n      const stars = Array.from({ length: Math.min(7, state.realm + 1) }, (_, index) => {\n        const x = 36 + index * 26 + (hashText(`${state.turn}-${index}`) % 8);\n        const y = 28 + (hashText(`${state.scene}-${index}`) % 32);\n        return `<circle cx=\"${x}\" cy=\"${y}\" r=\"2\" fill=\"${tone}\" opacity=\"0.8\"/>`;\n      }).join(\"\");\n      const karmaLines = state.karma > 12\n        ? `<path d=\"M250 36 C220 84 286 110 246 158 S288 232 228 256\" fill=\"none\" stroke=\"#d97869\" stroke-width=\"${Math.min(7, 1 + state.karma / 10)}\" opacity=\"0.55\"/>`\n        : \"\";\n      const halo = state.virtue > 60\n        ? `<circle cx=\"260\" cy=\"126\" r=\"54\" fill=\"none\" stroke=\"#7fc8a9\" stroke-width=\"3\" opacity=\"0.45\"/>`\n        : \"\";\n      const fragmentDoor = state.fragments >= 2\n        ? `<path d=\"M356 88 L414 58 L414 222 L356 196 Z\" fill=\"none\" stroke=\"#d8b35f\" stroke-width=\"3\"/><path d=\"M384 96 L384 200\" stroke=\"#d8b35f\" stroke-width=\"2\" opacity=\"0.7\"/>`\n        : \"\";\n\n      const sceneGlyphs = {\n        birth: `<path d=\"M36 236 L138 96 L238 236\" fill=\"none\" stroke=\"${tone}\" stroke-width=\"4\"/><path d=\"M96 236 L178 126 L270 236\" fill=\"none\" stroke=\"#b9b39f\" stroke-width=\"3\" opacity=\"0.75\"/>`,\n        sect: `<path d=\"M72 220 L72 132 L146 84 L220 132 L220 220\" fill=\"none\" stroke=\"${tone}\" stroke-width=\"4\"/><path d=\"M104 220 L104 156 L188 156 L188 220\" fill=\"none\" stroke=\"#b9b39f\" stroke-width=\"3\"/>`,\n        market: `<path d=\"M58 210 C96 130 154 130 194 210\" fill=\"none\" stroke=\"${shadow}\" stroke-width=\"5\"/><path d=\"M88 166 L178 166 M112 136 L154 206\" stroke=\"#d8b35f\" stroke-width=\"3\" opacity=\"0.7\"/>`,\n        demon: `<path d=\"M70 218 C94 132 146 104 208 142 C244 164 238 214 202 230\" fill=\"none\" stroke=\"${shadow}\" stroke-width=\"4\"/><circle cx=\"174\" cy=\"156\" r=\"5\" fill=\"#d97869\"/>`,\n        tribulation: `<path d=\"M178 36 L122 134 L174 126 L122 236 L250 106 L188 116 Z\" fill=\"${tone}\" opacity=\"0.18\" stroke=\"${tone}\" stroke-width=\"4\"/>`,\n        heartDemon: `<path d=\"M98 220 C94 130 164 86 222 142 C280 86 350 130 346 220\" fill=\"none\" stroke=\"#d97869\" stroke-width=\"5\"/><path d=\"M206 126 C230 162 204 186 232 222\" fill=\"none\" stroke=\"#d97869\" stroke-width=\"3\"/>`,\n        hell: `<path d=\"M36 230 C92 180 106 98 172 126 C238 154 248 84 316 116 C374 144 374 202 454 232\" fill=\"none\" stroke=\"#d97869\" stroke-width=\"5\" opacity=\"0.75\"/>`,\n        ascend: `<path d=\"M198 230 L198 76 L318 76 L318 230\" fill=\"none\" stroke=\"${tone}\" stroke-width=\"4\"/><path d=\"M228 104 C248 84 276 84 296 104\" fill=\"none\" stroke=\"#f4efdf\" stroke-width=\"3\" opacity=\"0.55\"/>`,\n        breakWheel: `<circle cx=\"256\" cy=\"148\" r=\"82\" fill=\"none\" stroke=\"${tone}\" stroke-width=\"4\"/><path d=\"M176 148 L336 148 M256 68 L256 228\" stroke=\"#b9b39f\" stroke-width=\"3\" opacity=\"0.65\"/>`\n      };\n\n      const glyph = sceneGlyphs[state.scene] || sceneGlyphs.birth;\n      return `<svg viewBox=\"0 0 512 288\" role=\"img\" aria-label=\"${scene.title}\">\n        <rect width=\"512\" height=\"288\" fill=\"${sky}\"/>\n        ${stars}\n        <path d=\"M0 248 C84 218 124 252 196 226 S330 230 512 206\" fill=\"none\" stroke=\"#b9b39f\" stroke-width=\"2\" opacity=\"0.3\"/>\n        ${karmaLines}\n        ${halo}\n        ${glyph}\n        ${fragmentDoor}\n        <circle cx=\"260\" cy=\"126\" r=\"${10 + state.realm * 4}\" fill=\"${tone}\" opacity=\"0.18\"/>\n        <path d=\"M248 116 L260 92 L272 116 L268 156 L252 156 Z\" fill=\"none\" stroke=\"#f4efdf\" stroke-width=\"3\"/>\n        <path d=\"M236 172 C252 190 278 190 294 172\" fill=\"none\" stroke=\"${tone}\" stroke-width=\"3\"/>\n      </svg>`;\n    }\n\n    function availableChoices(scene) {\n      return (scene.choices || []).filter(choice => !choice.requires || choice.requires(state));\n    }\n\n    function rebirth(choice) {\n      audio.play(choice.hell ? \"danger\" : \"rebirth\");\n      const old = cloneData(state);\n      const bonus = choice.bonus || {};\n      state = cloneData(freshLife);\n      state.life = old.life + 1;\n      state.memory = Math.max(0, old.memory + 1 + (bonus.memory || 0) - (choice.hell ? 2 : 0));\n      state.talent = Math.max(0, Math.floor(old.talent * 0.55) + Math.floor(state.memory / 3) - (choice.hell ? 2 : 0));\n      state.fragments = Math.max(0, old.fragments + (bonus.fragments || 0));\n      state.virtue = Math.max(20, 50 + (bonus.virtue || 0) - (choice.hell ? 12 : 0));\n      state.karma = choice.hell ? 15 : 0;\n      state.log = choice.hell\n        ? \"你从幽冥归来，开局更难，但记忆更锋利。\"\n        : \"你再度醒来。前世的痛苦没有白费，它们沉成了悟性。\";\n      render();\n    }\n\n    function hardReset() {\n      audio.play(\"rebirth\");\n      state = cloneData(freshLife);\n      render();\n    }\n\n    function choose(choice) {\n      audio.play(\"click\");\n      if (choice.hardReset) {\n        hardReset();\n        return;\n      }\n\n      if (choice.rebirth) {\n        rebirth(choice);\n        return;\n      }\n\n      if (choice.once) state.flags[choice.once] = true;\n      state.turn += 1;\n      const currentScene = state.scene;\n      const intendedScene = choice.to;\n      if (choice.effect) choice.effect(state);\n      if (state.scene === currentScene) state.scene = intendedScene;\n\n      if (state.years <= 0 && !scenes[state.scene].ending) {\n        state.scene = \"death\";\n        state.log = \"寿元走到尽头。好在你已经学会如何把失败带回下一世。\";\n      }\n\n      if (scenes[state.scene].ending) {\n        audio.play(state.scene === \"hell\" ? \"danger\" : \"ending\");\n      } else if (state.scene === \"afterBreak\") {\n        audio.play(\"break\");\n      } else if (state.scene === \"heartDemon\") {\n        audio.play(\"danger\");\n      }\n\n      render();\n    }\n\n    function render() {\n      const scene = scenes[state.scene] || scenes.birth;\n      if (!scenes[state.scene]) {\n        state.scene = \"birth\";\n        state.log = \"轮回出现裂隙，但你稳住了识海，重新回到山脚。\";\n      }\n      sceneTitle.textContent = scene.title;\n      sceneTitle.className = scene.ending ? \"ending\" : \"\";\n      sceneText.textContent = variedSceneText(scene, textOf(scene.text));\n      if (sceneSketch) sceneSketch.innerHTML = sketchForState(scene);\n\n      choices.innerHTML = \"\";\n      availableChoices(scene).forEach(choice => {\n        if (choice.once && state.flags[choice.once]) return;\n        const button = document.createElement(\"button\");\n        button.type = \"button\";\n        button.textContent = choice.text;\n        button.addEventListener(\"click\", () => choose(choice));\n        choices.appendChild(button);\n      });\n\n      life.textContent = `第 ${state.life} 世`;\n      realm.textContent = realms[state.realm];\n      path.textContent = state.path;\n      years.textContent = `${Math.max(0, state.years)} 年`;\n      qi.textContent = state.qi;\n      virtue.textContent = state.virtue;\n      virtue.className = state.virtue < 35 ? \"warning\" : \"\";\n      karma.textContent = state.karma;\n      karma.className = state.karma > 35 ? \"warning\" : \"\";\n      memory.textContent = state.memory;\n      talent.textContent = state.talent;\n      fragments.textContent = state.fragments;\n      log.textContent = state.log;\n\n      const nextThreshold = 28 + state.realm * 22 + Math.max(0, 50 - state.virtue) + Math.max(0, state.karma);\n      qiBar.style.width = `${Math.min(100, Math.round((state.qi / Math.max(1, nextThreshold)) * 100))}%`;\n    }\n\n    render();\n  </script>\n</body>\n</html>\n";

function htmlResponse(body, status = 200) {
  return new Response(body, {
    status,
    headers: {
      'content-type': 'text/html; charset=utf-8',
      'cache-control': 'public, max-age=60'
    }
  });
}

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname === '/' || url.pathname === '/index.html') {
      return Response.redirect(url.origin + '/text-adventure.html', 302);
    }

    if (url.pathname === '/text-adventure.html') {
      return htmlResponse(gameHtml);
    }

    return htmlResponse('Not found', 404);
  }
};
